//! Evidence bound to identity.
//!
//! Everything a team knows about a piece of code that is not the code —
//! reviewed by whom, audited under which control, benchmarked at what
//! number, generated by which model and checked by which human — is normally
//! attached to a pull request, a ticket, or a chat message. All of those
//! describe a *moment*, not a *meaning*. So the instant the code moves, every
//! claim about it is silently orphaned: the approval survives a rebase that
//! changed the logic, the audit still nominally covers a function rewritten
//! twice since, the benchmark number gets quoted for a year.
//!
//! An attestation is the same claim bound to a definition's content hash. It
//! is **live** while that hash is current and **void** the moment it is not.
//! No one decides whether it still applies; the identity model decides.
//!
//! The important property falls out of hashing and costs nothing extra: a
//! definition's hash covers its entire dependency cone, because references
//! are encoded as the hashes of what they reference. So reviewing `handler`
//! attests to everything `handler` can reach, and an edit to something four
//! calls away voids that review automatically. That is the guarantee code
//! review has always claimed and never had.
//!
//! Void attestations are never deleted. "This was reviewed at a hash that is
//! no longer current" is a fact worth keeping — it is the difference between
//! unreviewed and stale.

use crate::canon::{hex, Hash};
use crate::graph;
use crate::resolve::{DefId, Workspace};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

pub const FORMAT: &str = "rigid-attest/0";

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Attestation {
    /// `path/to/module.rg#name` as of the moment of attesting. A rename does
    /// not void the claim — the hash is what binds it — so this is the
    /// human-readable label, not the key.
    #[serde(rename = "ref")]
    pub reference: String,
    /// The identity this claim is about. This is the key.
    pub hash: String,
    /// What is being claimed: `reviewed`, `audited`, `benchmarked`,
    /// `generated`, or anything else a team decides to track. The vocabulary
    /// is deliberately open — the mechanism does not care.
    pub kind: String,
    pub by: String,
    /// UTC date, `YYYY-MM-DD`.
    pub at: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub note: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Ledger {
    pub format: String,
    #[serde(default)]
    pub attestations: Vec<Attestation>,
}

impl Default for Ledger {
    fn default() -> Self {
        Ledger {
            format: FORMAT.to_string(),
            attestations: Vec::new(),
        }
    }
}

pub fn path(root: &std::path::Path) -> std::path::PathBuf {
    root.join(".rigid-attest.json")
}

pub fn load(root: &std::path::Path) -> Result<Ledger, String> {
    let p = path(root);
    if !p.exists() {
        return Ok(Ledger::default());
    }
    let s = std::fs::read_to_string(&p).map_err(|e| format!("{}: {}", p.display(), e))?;
    let l: Ledger = serde_json::from_str(&s).map_err(|e| format!("{}: {}", p.display(), e))?;
    if l.format != FORMAT {
        return Err(format!(
            "{}: unknown ledger format '{}' (expected '{}')",
            p.display(),
            l.format,
            FORMAT
        ));
    }
    Ok(l)
}

pub fn save(root: &std::path::Path, l: &Ledger) -> Result<(), String> {
    let s = serde_json::to_string_pretty(l).map_err(|e| e.to_string())?;
    std::fs::write(path(root), s + "\n").map_err(|e| format!("{}: {}", path(root).display(), e))
}

/// Today, as `YYYY-MM-DD` UTC.
///
/// Days-to-civil after Howard Hinnant's algorithm — a date is worth having in
/// an audit ledger, and it is not worth a dependency.
pub fn today() -> String {
    let secs = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let z = secs.div_euclid(86_400) + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    format!("{:04}-{:02}-{:02}", y, m, d)
}

/// Which attestations still hold, indexed by the definition they cover.
///
/// An attestation is live when its hash is the current hash of some
/// definition in the workspace. Nothing else is consulted: not the name, not
/// the file, not when it was written.
pub fn live_index<'a>(
    l: &'a Ledger,
    ws: &Workspace,
    hashes: &HashMap<DefId, Hash>,
) -> HashMap<DefId, Vec<&'a Attestation>> {
    // A hash may belong to more than one definition — two definitions with
    // the same canonical form *are* the same code under two names — so a
    // claim about that identity is a claim about all of them.
    let mut by_hash: HashMap<String, Vec<DefId>> = HashMap::new();
    for d in 0..ws.defs.len() {
        if let Some(h) = hashes.get(&d) {
            by_hash.entry(hex(h)).or_default().push(d);
        }
    }
    let mut out: HashMap<DefId, Vec<&Attestation>> = HashMap::new();
    for a in &l.attestations {
        if let Some(ds) = by_hash.get(&a.hash) {
            for &d in ds {
                out.entry(d).or_default().push(a);
            }
        }
    }
    out
}

/// Attestations whose hash is no longer any definition's — stale evidence.
pub fn stale<'a>(
    l: &'a Ledger,
    ws: &Workspace,
    hashes: &HashMap<DefId, Hash>,
) -> Vec<&'a Attestation> {
    let current: std::collections::HashSet<String> = (0..ws.defs.len())
        .filter_map(|d| hashes.get(&d).map(hex))
        .collect();
    l.attestations
        .iter()
        .filter(|a| !current.contains(&a.hash))
        .collect()
}

/// Definitions a `--require KIND` gate should cover.
///
/// Tests are excluded: a test attesting to itself is circular, and the point
/// of the gate is the code the tests are about. Standard-library modules are
/// excluded because they are not the workspace's to review.
pub fn gated(ws: &Workspace) -> Vec<DefId> {
    (0..ws.defs.len())
        .filter(|&d| {
            let i = &ws.defs[d];
            !i.poisoned && !i.name.starts_with("test_") && !i.module_path.starts_with("std/")
        })
        .collect()
}

/// Everything `d` reaches, `d` included — the span a claim about `d` covers.
pub fn cone(ws: &Workspace, d: DefId) -> Vec<DefId> {
    let mut seen = vec![false; ws.defs.len()];
    let mut stack = vec![d];
    let mut out = Vec::new();
    while let Some(x) = stack.pop() {
        if seen[x] {
            continue;
        }
        seen[x] = true;
        out.push(x);
        for &n in &ws.edges[x] {
            stack.push(n);
        }
    }
    out.sort();
    out
}

pub fn describe(ws: &Workspace, d: DefId) -> String {
    graph::ref_str(ws, d)
}
